{"path": "/app/recover.py", "content": "#!/usr/bin/env python3
"""Recover rows from a sqlite database that was corrupted by binary truncation.

The file only survives as a single 4096-byte image of a b-tree leaf table page:
the 100-byte database header (and any following pages) were cut away, leaving the
page's b-tree header at file offset 0.  We therefore re-read the page header and
cell pointer array manually instead of relying on sqlite.
"""
import json
import struct

RAW = "/app/trunc.db"
OUT = "/app/recover.json"


def read_varint(buf, off):
    val = 0
    for i in range(9):
        b = buf[off + i]
        if i == 8:
            val = (val << 8) | b
            return val, off + 9
        val = (val << 7) | (b & 0x7F)
        if not (b & 0x80):
            return val, off + i + 1
    return val, off + 9


def serial_size(t):
    if t in (0, 8, 9):
        return 0
    if t == 1:
        return 1
    if t == 2:
        return 2
    if t == 3:
        return 3
    if t == 4:
        return 4
    if t == 5:
        return 6
    if t in (6, 7):
        return 8
    if t >= 12:
        return (t - 13) // 2
    raise ValueError("bad serial type %d" % t)


def decode_value(t, raw):
    if t == 0:
        return None
    if t == 7:
        return struct.unpack(">d", raw)[0]
    if t == 8:
        return 0
    if t == 9:
        return 1
    if 1 <= t <= 6:
        return int.from_bytes(raw, "big", signed=True)
    if t >= 13 and t % 2 == 1:
        return raw.decode("utf-8")
    return raw


def decode_record(payload):
    hdr_size = payload[0]
    types = []
    off = 1
    while off < hdr_size:
        t, off = read_varint(payload, off)
        types.append(t)
    data = payload[hdr_size:]
    off = 0
    values = []
    for t in types:
        size = serial_size(t)
        raw = data[off:off + size]
        off += size
        values.append(decode_value(t, raw))
    return values


def page_cells(page):
    """Yield (rowid, payload) for every intact cell of a b-tree leaf table page."""
    if page[0] != 0x0D:  # table leaf page
        raise ValueError("unsupported page type 0x%02x" % page[0])
    ncell = int.from_bytes(page[3:5], "big")
    content_start = int.from_bytes(page[5:7], "big")
    ptrs = [int.from_bytes(page[8 + 2 * i:10 + 2 * i], "big") for i in range(ncell)]
    for ptr in ptrs:
        if not content_start <= ptr < len(page):
            continue
        off = ptr
        payload_len, off = read_varint(page, off)
        rowid, off = read_varint(page, off)
        payload = page[off:off + max(payload_len, 0)]
        if len(payload) < payload_len:
            # cell was cut off by the truncation -> skip the partial row
            continue
        yield rowid, payload


def main():
    buf = open(RAW, "rb").read()

    # The database header is gone; find the b-tree page header.  In the intact
    # image it sits at offset 0, but look for it in case padding survived.
    page = None
    for off in (0, 100):
        if off < len(buf) and buf[off] == 0x0D:
            page = buf[off:off + 4096]
            break
    if page is None:
        page = buf

    rows = {}
    for rowid, payload in page_cells(page):
        values = decode_record(payload)
        # Skip the leading placeholder column; the payload carries
        # (NULL, word, value) for the rows in this file.
        cells = [v for v in values if v is not None]
        word = next((v for v in values if isinstance(v, str)), None)
        value = None
        for v in reversed(values):
            if isinstance(v, (int, float)):
                value = v
                break
        if word is None:
            continue
        rows[rowid] = {"word": word, "value": value}

    out = [rows[r] for r in sorted(rows)]
    with open(OUT, "w") as fh:
        json.dump(out, fh, indent=2)
    print("recovered %d rows -> %s" % (len(out), OUT))


if __name__ == "__main__":
    main()"}

